(function(){function mcp(){var SH=Java.loadClass('net.neoforged.neoforge.server.ServerLifecycleHooks');return SH.getCurrentServer();}
function pl(){return mcp().getPlayerList().getPlayers().get(0);}
function reg(){return Java.loadClass('net.minecraft.core.registries.BuiltInRegistries');}
function rl(){return Java.loadClass('net.minecraft.resources.ResourceLocation');}
function itemOf(id){return reg().ITEM.get(rl().parse(id));}
function stackOf(id,n){var IS=Java.loadClass('net.minecraft.world.item.ItemStack');return new IS(itemOf(id),n);}
function cnt(p,id){var n=0;var list=p.getInventory().items;for(var i=0;i<list.size();i++){var st=list.get(i);if(!st.isEmpty()&&String(reg().ITEM.getKey(st.getItem()))===id)n+=st.getCount();}var off=p.getInventory().offhand;for(var j=0;j<off.size();j++){var so=off.get(j);if(!so.isEmpty()&&String(reg().ITEM.getKey(so.getItem()))===id)n+=so.getCount();}return n;}
function cur(p){var C=Java.loadClass('top.theillusivec4.curios.api.CuriosApi');return C.getCuriosInventory(p).get();}
function stand(p){return cur(p).getStacksHandler('stand').get().getStacks();}
function purge(p,r){var lvl=p.level;var names=['net.minecraft.world.entity.monster.Pillager','net.minecraft.world.entity.animal.Cow','com.merlinkitsune.astral_dice.entity.RepulsionEntity','net.minecraft.world.entity.item.ItemEntity'];var n=0;for(var k=0;k<names.length;k++){var l=lvl.getEntitiesOfClass(Java.loadClass(names[k]),p.getBoundingBox().inflate(r));for(var i=0;i<l.size();i++){l.get(i).discard();n++;}}return n;}
var LSM=Java.loadClass('com.merlinkitsune.astral_dice.item.sign.LinglingSignManager');
var MA=Java.loadClass('com.merlinkitsune.astral_dice.component.ModAttachments');
var CM=Java.loadClass('com.merlinkitsune.astral_dice.item.ChargeManager');
var CS=Java.loadClass('com.merlinkitsune.astral_dice.item.CurioSlotUtil');
var MT=Java.loadClass('com.merlinkitsune.astral_dice.entity.ModEntityTypes');
var ET=Java.loadClass('net.minecraft.world.entity.EntityType');
var Pillager=Java.loadClass('net.minecraft.world.entity.monster.Pillager');
var RepulsionEntity=Java.loadClass('com.merlinkitsune.astral_dice.entity.RepulsionEntity');
var ItemEntity=Java.loadClass('net.minecraft.world.entity.item.ItemEntity');
var GameType=Java.loadClass('net.minecraft.world.level.GameType');
var Attributes=Java.loadClass('net.minecraft.world.entity.ai.attributes.Attributes');
var BSI=Java.loadClass('com.merlinkitsune.astral_dice.item.sign.BaseSignItem');
var ME=Java.loadClass('com.merlinkitsune.astral_dice.effect.ModEffects');
var HC=Java.loadClass('net.minecraft.world.InteractionHand');
var SIGN='astral_dice:lingling_sign';
var REP='astral_dice:effect_card_repulsion';
var BAR='astral_dice:effect_card_barricade';
var p=pl();

var purged=purge(p,64);
p.setGameMode(GameType.CREATIVE);
p.getInventory().clearContent();
MA.setLinglingGranted(p,false);
MA.setLinglingBonusCharge(p,0);
MA.setSignActiveCooldownEnd(p,0);
MA.setSignActiveMaxCooldown(p,0);
LSM.clearAll(p);
cur(p).getStacksHandler('dice').get().getStacks().setStackInSlot(0,stackOf('astral_dice:dice',1));
var IS=Java.loadClass('net.minecraft.world.item.ItemStack');
stand(p).setStackInSlot(0,IS.EMPTY);
return {ok:true,granted:MA.isLinglingGranted(p),hasDice:CS.hasDiceEquipped(p),eq:LSM.isEquipped(p),rep:cnt(p,REP),bar:cnt(p,BAR),purged:purged};
})()

